{{ config(
    tags=['m_MT_PRODUCT_HWSW_ANNUITY']
) }}
SELECT
   T.SALES_TERRITORY_KEY,
   T.SALES_REP_NUMBER,
   T.DV_ATTRIBUTION_CD,
   T.DV_SALES_ORDER_LINE_KEY,
   T.ANNUAL_NET,
   T.SALES_ORDER_KEY,
   T.CNTRCT_DURATION,
   T.BKGS_MEASURE_TRANS_TYPE_CODE,
   T.CORPORATE_BOOKINGS_FLG,
   T.REVENUE_RECOGNITION_FLG,
   T.CONTRACT_START_DATE,
   T.CONTRACT_END_DATE,
   T.ANNUALIZD_FLAG,
   T.SHIP_TO_CUSTOMER_KEY,
   T.SERVICE_FLG,
   T.DV_PRODUCT_KEY,
   T.BILL_TO_CUSTOMER_KEY,
   T.BOOKINGS_MEASURE_KEY,
   T.END_CUSTOMER_KEY_NOT_OFFSETED,
   T.END_CUSTOMER_KEY,
   T.BOOKINGS_PROCESS_DATE,
   T.POS_TRX_ID_INT,
   T.SOURCE_ORDER_NUMBER,
   T.NET_SPREAD_FLG,
   T.DV_AR_TRX_LINE_KEY,
   T.TRANSACTION_DATETIME,
   T.CANCEL_CODE,
   T.IC_REVENUE_FLG,
   T.CHARGES_FLG,
   T.MISC_FLG,
   T.INTERNATIONAL_DEMO_FLG,
   T.REPLACEMENT_DEMO_FLG,
   T.REVENUE_FLG,
   T.CONVERSION_RT,
   T.TRANSACTION_NAME,
   T.FMV_FLG,
   T.XCAT_FLAG,
   T.OFFER_TYPE_NAME,
   T.RECURRING_OFFER_FLAG,
   T.ELA_FLG,
   T.FISCAL_YEAR_MTH_INT,
   T.SALES_ADJ_LINE_NUMBER_INT,
   T.SALES_ADJ_NUMBER_INT,
   T.DEAL_ID,
   T.REVENUE_TRANSFER_KEY,
   T.DV_SO_SBSCRPTN_ITM_SLS_TRX_KEY,
   T.SK_OFFER_ATTRIBUTION_ID_INT,
   T.ADJUSTMENT_TYPE_CODE,
   ---- SHOULD CHK
   T.ADJUSTMENT_CODE,
   T.SOLD_TO_CUSTOMER_KEY,
   T.PARTNER_SITE_PARTY_KEY,
   T.ROUTE_TO_MARKET_CD,
   T.AS_OF_FSC_MTH_RTM_CD,
   T.BOOKINGS_NET,
   COALESCE(T.MY_NET, 0) AS MY_NET,
   T.PRODUCT_CLASSIFICATION,
   T.WEEK_NAME,
   T.PERIOD_ID,
   T.WEEK_ID,
   'UNKNOWN' as RU_BK_SERVICE_PROD_SUBGROUP_ID,
   T.PRODUCT_KEY,
   T.ANNUITY_AMT,
   'N' AS TRUE_UP_FLG,
   'AMY' AS BOOKING_TYPE_CD,
   T.ANNUITY_SWITCHING,
   CURRENT_TIMESTAMP(0) AS EDW_CREATE_DTM,
   CURRENT_USER() AS EDW_CREATE_USER,
   CURRENT_TIMESTAMP(0) AS EDW_UPDATE_DTM,
   CURRENT_USER() AS EDW_UPDATE_USER,
   T.SALES_MOTION_CD,
   T.SUMMARY_QUOTE_FLG,
   T.ADJUSTMENT_DESCR_KEY,
   T.DV_RECURRING_OFFER_CD,
   T.SK_SALES_MOTION_ATTRIB_KEY,
   T.WIPS_ORIGINATOR_ID_INT,
   /*Added as part of SFP Q4FY21 Rel*/
   T.MAGIC_KEY_ID,
   T.DSV_FLG
FROM
   (
      SELECT
         RSTD.DV_SALES_ORDER_LINE_KEY,
         RSTD.DV_ATTRIBUTION_CD,
         RSTD.PRODUCT_KEY,
         RSTD.SALES_TERRITORY_KEY,
         RSTD.SALES_REP_NUMBER AS SALES_REP_NUM,
         RSTD.SALES_ORDER_KEY,
         RSTD.BKGS_MEASURE_TRANS_TYPE_CODE AS DV_ANNUAL_NET_AMT,
         RSTD.CORPORATE_BOOKINGS_FLG,
         RSTD.SERVICE_FLG,
         RSTD.DV_PRODUCT_KEY,
         RSTD.BILL_TO_CUSTOMER_KEY,
         RSTD.SHIP_TO_CUSTOMER_KEY,
         --RFDY.DV_FISCAL_QUARTER_ID AS QUARTER_ID,
         RSTD.BOOKINGS_MEASURE_KEY,
         RSTD.BOOKINGS_PROCESS_DATE AS DV_CONTRACT_DURATION,
         RSTD.ADJUSTMENT_TYPE_CODE AS BKGS_MEASURE_TRANS_TYPE_CD,
         RSTD.ADJUSTMENT_CODE AS DV_REVENUE_RECOGNITION_FLG,
         RSTD.DV_AR_TRX_LINE_KEY,
         RSTD.SOLD_TO_CUSTOMER_KEY,
         RSTD.DV_END_CUSTOMER_KEY AS RU_SERVICE_CONTRACT_START_DTM,
         RSTD.SK_OFFER_ATTRIBUTION_ID_INT,
         NBCM.PARTNER_SITE_PARTY_KEY,
         RSTD.ELA_FLG,
         --RSTD.FISCAL_YEAR_QUARTER_NUMBER_INT AS QUARTER_NUMBER_INT,
         RSTD.DSV_FLG,
         RSTD.REVENUE_FLG,
         RSTD.IC_REVENUE_FLG,
         RSTD.REPLACEMENT_DEMO_FLG,
         RSTD.INTERNATIONAL_DEMO_FLG,
         RSTD.CHARGES_FLG,
         RSTD.MISC_FLG,
         RSTD.TRANSACTION_DATETIME AS RU_SERVICE_CONTRACT_END_DTM,
         RSTD.CANCEL_CODE AS DV_ANNUALIZED_FLG,
         RSTD.CONVERSION_RT,
         RSTD.REVENUE_TRANSFER_KEY,
         RSTD.DV_SO_SBSCRPTN_ITM_SLS_TRX_KEY,
         RSTD.SALES_MOTION_CD,
         RSTD.SUMMARY_QUOTE_FLG,
         RSTD.ADJUSTMENT_DESCR_KEY,
         RSTD.DV_RECURRING_OFFER_CD,
         RSTD.SK_SALES_MOTION_ATTRIB_KEY,
         RSTD.WIPS_ORIGINATOR_ID_INT,
         /*Added as part of SFP Q4FY21 Rel*/
         NBCM.MAGIC_KEY_ID,
         (RSTD.DD_COMP_US_NET_PRICE_AMOUNT * NPCA.ALLOCATION_PCT) AS NOT_OFFSETED_END_CUSTOMER_KEY,
         CASE
            WHEN COLLATE(NPCA.BK_PRDT_ALLCTN_CLSFCTN_CD, 'en-ci-rtrim') = 'Hardware'
               THEN RSTD.DD_COMP_US_NET_PRICE_AMOUNT * NPCA.ALLOCATION_PCT
            ELSE RSTD.DV_ANNUALIZED_US_NET_AMT * NPCA.ALLOCATION_PCT
         END AS DV_END_CUSTOMER_KEY,
         NPCA.BK_PRDT_ALLCTN_CLSFCTN_CD AS BOOKINGS_PROCESS_DT,
         CASE
            WHEN COLLATE(PRODUCT_CLASSIFICATION, 'en-ci-rtrim') = 'Software'
               THEN CASE
                  WHEN COLLATE(NPCA.BK_PRDT_ALLCTN_CLSFCTN_CD, 'en-ci-rtrim') = 'Hardware'
                     THEN 0
                  ELSE RSTD.DV_MULTIYEAR_US_NET_AMT * NPCA.ALLOCATION_PCT
               END
            ELSE CAST(0.00 AS DECIMAL(36, 8))
         END AS BK_POS_TRANSACTION_ID_INT,
         CAST(0.00 AS DECIMAL(18, 6)) AS ANNUITY_AMT,
         RFDY.FISCAL_YEAR_MONTH_INT AS DV_SOURCE_ORDER_NUM_INT,
         RSTD.DV_CONTRACT_DURATION AS DV_NET_SPREAD_FLG,
         RSTD.RU_SERVICE_CONTRACT_START_DTM AS TRANSACTION_DTM,
         RSTD.RU_SERVICE_CONTRACT_END_DTM AS CANCEL_CD,
         CASE
            WHEN COLLATE(NPCA.BK_PRDT_ALLCTN_CLSFCTN_CD, 'en-ci-rtrim') = 'Hardware'
               THEN 'Y'
            ELSE RSTD.DV_ANNUALIZED_FLG
         END AS DV_TRANSACTION_NAME,
         RSTD.DV_REVENUE_RECOGNITION_FLG AS DV_FMV_FLG,
         RFDY.FISCAL_WEEK_NAME AS XCAT_FLG,
         RFDY.DV_FISCAL_YR_MNTH_WEEK_NUM_INT AS BK_OFFER_TYPE_NAME,
         RSTD.DV_NET_SPREAD_FLG AS RECURRING_OFFER_FLG,
         RSTD.DV_SOURCE_ORDER_NUM_INT AS DV_FISCAL_YEAR_MTH_NUMBER_INT,
         RSTD.BK_POS_TRANSACTION_ID_INT AS BK_SALES_ADJ_LINE_NUMBER_INT,
         RSTD.END_CUSTOMER_KEY AS BK_SALES_ADJ_NUMBER_INT,
         RSTD.DV_FMV_FLG AS DV_DEAL_ID,
         --Dummy Column to keep the default view intact.
         CAST(1 AS NUMBER(38, 18)) AS ADJUSTMENT_TYPE_CD,
         RSTD.BK_OFFER_TYPE_NAME AS IDE_ADJUSTMENT_CD,
         RSTD.XCAT_FLG AS DV_ROUTE_TO_MARKET_CD,
         RSTD.RECURRING_OFFER_FLG AS DV_AS_OF_FSC_MTH_RTM_CD,
         NBCM.DV_ROUTE_TO_MARKET_CD AS DV_CA_SERVICE_BOOOKINGS_PCT,
         NBCM.DV_AS_OF_FSC_MTH_RTM_CD AS DV_MY_NET_PCT,
         RSTD.DV_TRANSACTION_NAME AS BK_PRDT_ALLCTN_CLSFCTN_CD,
         RSTD.BK_SALES_ADJ_LINE_NUMBER_INT AS FISCAL_WEEK_NAME,
         RSTD.BK_SALES_ADJ_NUMBER_INT AS FISCAL_YEAR_MONTH_INT,
         RSTD.DV_DEAL_ID AS DV_FISCAL_YR_MNTH_WEEK_NUM_INT,
         RSTD.DV_FISCAL_YEAR_MTH_NUMBER_INT AS RU_BK_SERVICE_PROD_SUBGROUP_ID
      FROM /*BV_RSTD_BKGS_MSR_ANLZD_MY*/
         {{ var('m_MT_PRODUCT_HWSW_ANNUITY_SLSORDVWDB') }}.MT_RSTD_BKGS_MEASURE RSTD
         INNER JOIN
            {{ var('m_MT_PRODUCT_HWSW_ANNUITY_SLSORDVWDB') }}.N_BOOKINGS_CHANNEL_MEASURE NBCM
            ON RSTD.BOOKINGS_MEASURE_KEY = NBCM.BOOKINGS_MEASURE_KEY
            AND RSTD.BOOKINGS_PROCESS_DATE = NBCM.BOOKINGS_PROCESS_DATE
            AND RSTD.BKGS_MEASURE_TRANS_TYPE_CODE = NBCM.BKGS_MEASURE_TRANS_TYPE_CODE
         INNER JOIN
            {{ var('m_MT_PRODUCT_HWSW_ANNUITY_COMREFVWDB') }}.N_PRDT_TO_PRDT_CLSFTN_ALCTN NPCA
            ON NPCA.DV_FISCAL_YEAR_QUARTER_NUM_INT = RSTD.FISCAL_YEAR_QUARTER_NUMBER_INT
            AND NPCA.PRODUCT_KEY = RSTD.PRODUCT_KEY
            AND RTRIM(NPCA.BK_PRDT_ALLCTN_METRIC_CD) IN (COLLATE('BOOKINGS', 'en-ci-rtrim'), COLLATE('UNKNOWN', 'en-ci-rtrim'))
            AND COLLATE(RSTD.RSTD_DEL_RECORD_FLG, 'en-ci-rtrim') = 'N'
         --AND RSTD.DV_FISCAL_YEAR_MTH_NUMBER_INT >= 201401 
         /*BV_RSTD_BKGS_MSR_ANLZD_MY*/
         INNER JOIN /*BV_FISCAL_DAY_TO_YEAR*/
            {{ var('m_MT_PRODUCT_HWSW_ANNUITY_COMREFVWDB') }}.R_FISCAL_DAY_TO_YEAR RFDY
            ON RSTD.BOOKINGS_PROCESS_DATE = RFDY.CALENDAR_DATE
            AND RSTD.DV_FISCAL_YEAR_MTH_NUMBER_INT >= (
               SELECT
                  FISCAL_YEAR_MONTH_INT
               FROM
                  {{ var('m_MT_PRODUCT_HWSW_ANNUITY_STGDB') }}.WI_PRODUCT_HWSW_MONTH_CTRL
            )
      WHERE
         COLLATE(RSTD.SERVICE_FLG, 'en-ci-rtrim') = 'N'
         AND COLLATE(NPCA.BK_PRDT_ALLCTN_CLSFCTN_CD, 'en-ci-rtrim') <> 'Service'
      UNION ALL
      --Annuity RSTD--
      SELECT
         CAST(0.00 AS DECIMAL(36, 8)) AS SALES_REP_NUM,
         CAST(0.00 AS DECIMAL(36, 8)) AS DV_ANNUAL_NET_AMT,
         CAST(0.00 AS DECIMAL(36, 8)) AS DV_CONTRACT_DURATION,
         CASE
            WHEN COLLATE(PRODUCT_CLASSIFICATION, 'en-ci-rtrim') = 'SOFTWARE'
               THEN BMA.DV_ANNUITY_AMT
            ELSE CAST(0.00 AS DECIMAL(18, 6))
         END AS ANNUITY_AMT,
         BMA.DV_FISCAL_YEAR_ANNUITY_MTH_INT AS BKGS_MEASURE_TRANS_TYPE_CD,
         BMA.DV_SALES_ORDER_LINE_KEY,
         BMA.DV_ATTRIBUTION_CD,
         BMA.PRODUCT_KEY,
         BMA.SALES_TERRITORY_KEY,
         BMA.SALES_REP_NUMBER AS RU_SERVICE_CONTRACT_START_DTM,
         RSTD.SALES_ORDER_KEY,
         BMA.DV_CONTRACT_DURATION AS RU_SERVICE_CONTRACT_END_DTM,
         BMA.RU_SERVICE_CONTRACT_START_DTM AS DV_ANNUALIZED_FLG,
         BMA.RU_SERVICE_CONTRACT_END_DTM AS NOT_OFFSETED_END_CUSTOMER_KEY,
         BMA.DV_ANNUALIZED_FLG AS DV_END_CUSTOMER_KEY,
         BMA.BKGS_MEASURE_TRANS_TYPE_CODE AS BOOKINGS_PROCESS_DT,
         BMA.CORPORATE_BOOKINGS_FLG,
         BMA.DV_REVENUE_RECOGNITION_FLG,
         BMA.SERVICE_FLG,
         RSTD.DV_PRODUCT_KEY,
         BMA.BILL_TO_CUSTOMER_KEY,
         BMA.SHIP_TO_CUSTOMER_KEY,
         RFDY.FISCAL_WEEK_NAME AS BK_POS_TRANSACTION_ID_INT,
         RFDY.DV_FISCAL_YR_MNTH_WEEK_NUM_INT AS DV_SOURCE_ORDER_NUM_INT,
         /*(SUBSTR(TRIM(BMA.DV_FISCAL_YEAR_ANNUITY_MTH_INT),1,4) || (CASE WHEN SUBSTR(TRIM(BMA.DV_FISCAL_YEAR_ANNUITY_MTH_INT),5,6)='01' THEN 'Q1'
         WHEN SUBSTR(TRIM(BMA.DV_FISCAL_YEAR_ANNUITY_MTH_INT),5,6)='02' THEN 'Q1'
         WHEN SUBSTR(TRIM(BMA.DV_FISCAL_YEAR_ANNUITY_MTH_INT),5,6)='03' THEN 'Q1'
         WHEN SUBSTR(TRIM(BMA.DV_FISCAL_YEAR_ANNUITY_MTH_INT),5,6)='04' THEN 'Q2'
         WHEN SUBSTR(TRIM(BMA.DV_FISCAL_YEAR_ANNUITY_MTH_INT),5,6)='05' THEN 'Q2'
         WHEN SUBSTR(TRIM(BMA.DV_FISCAL_YEAR_ANNUITY_MTH_INT),5,6)='06' THEN 'Q2'
         WHEN SUBSTR(TRIM(BMA.DV_FISCAL_YEAR_ANNUITY_MTH_INT),5,6)='07' THEN 'Q3'
         WHEN SUBSTR(TRIM(BMA.DV_FISCAL_YEAR_ANNUITY_MTH_INT),5,6)='08' THEN 'Q3'
         WHEN SUBSTR(TRIM(BMA.DV_FISCAL_YEAR_ANNUITY_MTH_INT),5,6)='09' THEN 'Q3'
         WHEN SUBSTR(TRIM(BMA.DV_FISCAL_YEAR_ANNUITY_MTH_INT),5,6)='10' THEN 'Q4'
         WHEN SUBSTR(TRIM(BMA.DV_FISCAL_YEAR_ANNUITY_MTH_INT),5,6)='11' THEN 'Q4'
         WHEN SUBSTR(TRIM(BMA.DV_FISCAL_YEAR_ANNUITY_MTH_INT),5,6)='12' THEN 'Q4' ELSE -9999 END)) AS QUARTER_ID,*/
         BMA.BOOKINGS_MEASURE_KEY,
         BMA.BOOKINGS_PROCESS_DATE AS DV_NET_SPREAD_FLG,
         RSTD.DV_NET_SPREAD_FLG AS TRANSACTION_DTM,
         BMA.ADJUSTMENT_TYPE_CODE AS CANCEL_CD,
         BMA.ADJUSTMENT_CODE AS DV_TRANSACTION_NAME,
         RSTD.DV_SOURCE_ORDER_NUM_INT AS DV_FMV_FLG,
         RSTD.BK_POS_TRANSACTION_ID_INT AS XCAT_FLG,
         RSTD.DV_AR_TRX_LINE_KEY,
         RSTD.SOLD_TO_CUSTOMER_KEY,
         RSTD.DV_END_CUSTOMER_KEY AS BK_OFFER_TYPE_NAME,
         RSTD.END_CUSTOMER_KEY AS RECURRING_OFFER_FLG,
         RSTD.DV_FMV_FLG AS DV_FISCAL_YEAR_MTH_NUMBER_INT,
         RSTD.SK_OFFER_ATTRIBUTION_ID_INT,
         NPCA.BK_PRDT_ALLCTN_CLSFCTN_CD AS BK_SALES_ADJ_LINE_NUMBER_INT,
         --DUMMY COLUMN TO KEEP THE DEFAULT VIEW INTACT.
         CAST(1 AS NUMBER(38, 18)) AS BK_SALES_ADJ_NUMBER_INT,
         NBCM.PARTNER_SITE_PARTY_KEY,
         RSTD.BK_OFFER_TYPE_NAME AS DV_DEAL_ID,
         RSTD.ELA_FLG,
         RSTD.XCAT_FLG AS ADJUSTMENT_TYPE_CD,
         RSTD.RECURRING_OFFER_FLG AS IDE_ADJUSTMENT_CD,
         --RSTD.FISCAL_YEAR_QUARTER_NUMBER_INT AS QUARTER_NUMBER_INT,
         RSTD.DSV_FLG,
         RSTD.REVENUE_FLG,
         RSTD.IC_REVENUE_FLG,
         RSTD.REPLACEMENT_DEMO_FLG,
         RSTD.INTERNATIONAL_DEMO_FLG,
         RSTD.CHARGES_FLG,
         RSTD.MISC_FLG,
         NBCM.DV_ROUTE_TO_MARKET_CD AS DV_ROUTE_TO_MARKET_CD,
         NBCM.DV_AS_OF_FSC_MTH_RTM_CD AS DV_AS_OF_FSC_MTH_RTM_CD,
         RSTD.TRANSACTION_DATETIME AS DV_CA_SERVICE_BOOOKINGS_PCT,
         RSTD.CANCEL_CODE AS DV_MY_NET_PCT,
         RSTD.DV_TRANSACTION_NAME AS BK_PRDT_ALLCTN_CLSFCTN_CD,
         RSTD.CONVERSION_RT,
         RSTD.BK_SALES_ADJ_LINE_NUMBER_INT AS FISCAL_WEEK_NAME,
         RSTD.BK_SALES_ADJ_NUMBER_INT AS FISCAL_YEAR_MONTH_INT,
         RSTD.REVENUE_TRANSFER_KEY,
         RSTD.DV_SO_SBSCRPTN_ITM_SLS_TRX_KEY,
         RSTD.DV_DEAL_ID AS DV_FISCAL_YR_MNTH_WEEK_NUM_INT,
         BMA.DV_FISCAL_YEAR_MONTH_INT AS RU_BK_SERVICE_PROD_SUBGROUP_ID,
         RSTD.SALES_MOTION_CD,
         RSTD.SUMMARY_QUOTE_FLG,
         RSTD.ADJUSTMENT_DESCR_KEY,
         RSTD.DV_RECURRING_OFFER_CD,
         RSTD.SK_SALES_MOTION_ATTRIB_KEY,
         RSTD.WIPS_ORIGINATOR_ID_INT,
         /*Added as part of SFP Q4FY21 Rel*/
         NBCM.MAGIC_KEY_ID
      FROM
         {{ var('m_MT_PRODUCT_HWSW_ANNUITY_SLSORDVWDB') }}.MT_RSTD_BKGS_MSR_ANNUITY BMA
         INNER JOIN
            {{ var('m_MT_PRODUCT_HWSW_ANNUITY_COMREFVWDB') }}.R_FISCAL_DAY_TO_YEAR RFDY
            ON BMA.DV_ANNUITY_DATE = RFDY.CALENDAR_DATE
            AND BMA.DV_FISCAL_YEAR_MONTH_INT >= (
               SELECT
                  FISCAL_YEAR_MONTH_INT
               FROM
                  {{ var('m_MT_PRODUCT_HWSW_ANNUITY_STGDB') }}.WI_PRODUCT_HWSW_MONTH_CTRL
            ),
         {{ var('m_MT_PRODUCT_HWSW_ANNUITY_SLSORDVWDB') }}.MT_RSTD_BKGS_MEASURE RSTD
         INNER JOIN
            {{ var('m_MT_PRODUCT_HWSW_ANNUITY_SLSORDVWDB') }}.N_BOOKINGS_CHANNEL_MEASURE NBCM
            ON RSTD.BOOKINGS_MEASURE_KEY = NBCM.BOOKINGS_MEASURE_KEY
            AND RSTD.BOOKINGS_PROCESS_DATE = NBCM.BOOKINGS_PROCESS_DATE
            AND RSTD.BKGS_MEASURE_TRANS_TYPE_CODE = NBCM.BKGS_MEASURE_TRANS_TYPE_CODE
         INNER JOIN
            {{ var('m_MT_PRODUCT_HWSW_ANNUITY_COMREFVWDB') }}.N_PRDT_TO_PRDT_CLSFTN_ALCTN NPCA
            ON NPCA.DV_FISCAL_YEAR_QUARTER_NUM_INT = RSTD.FISCAL_YEAR_QUARTER_NUMBER_INT
            AND NPCA.PRODUCT_KEY = RSTD.PRODUCT_KEY
            AND RTRIM(NPCA.BK_PRDT_ALLCTN_METRIC_CD) IN (COLLATE('BOOKINGS', 'en-ci-rtrim'), COLLATE('UNKNOWN', 'en-ci-rtrim'))
            AND COLLATE(RSTD.RSTD_DEL_RECORD_FLG, 'en-ci-rtrim') = 'N'
      /*AND RSTD.DV_FISCAL_YEAR_MTH_NUMBER_INT >= 201401 */
      WHERE
         1 = 1
         AND (BMA.BOOKINGS_MEASURE_KEY = RSTD.BOOKINGS_MEASURE_KEY
         AND BMA.BOOKINGS_PROCESS_DATE = RSTD.BOOKINGS_PROCESS_DATE
         AND BMA.BKGS_MEASURE_TRANS_TYPE_CODE = RSTD.BKGS_MEASURE_TRANS_TYPE_CODE
         AND BMA.SALES_REP_NUMBER = RSTD.SALES_REP_NUMBER
         AND BMA.SALES_TERRITORY_KEY = RSTD.SALES_TERRITORY_KEY)
         AND BMA.DV_FISCAL_YEAR_ANNUITY_MTH_INT <> -9999
         AND COLLATE(BMA.DV_SRVC_BOOKINGS_TYPE, 'en-ci-rtrim') = 'ANNUITY'
         AND COLLATE(BMA.SERVICE_FLG, 'en-ci-rtrim') = 'N'
         AND COLLATE(NPCA.BK_PRDT_ALLCTN_CLSFCTN_CD, 'en-ci-rtrim') <> 'SERVICE'
         AND COLLATE(NPCA.BK_PRDT_ALLCTN_CLSFCTN_CD, 'en-ci-rtrim') <> 'HARDWARE'
   ) T